from pathlib import Path
import json,html,subprocess,hashlib
OUT=Path(__file__).resolve().parents[1];ROOT=OUT.parents[2];FW=ROOT/'Framework-Edicion-Social';FF='/opt/homebrew/opt/ffmpeg-full/bin/ffmpeg'
M=json.loads((OUT/'manifest.json').read_text());data=[]
for i,m in enumerate(M):
 files={}
 for role in ['voz-sola','musica','efectos']:
  p=OUT/f"renders/v2/{m['id']}-{role}.m4a"
  subprocess.run([FF,'-v','error','-i',str(p.with_suffix('.wav')),'-c:a','aac','-b:a','256k','-movflags','+faststart','-metadata','comment=Créditos y cambios: CREDITOS.md','-y',str(p)],check=True)
  m['files'][str(p.relative_to(OUT))]={'sha256':hashlib.sha256(p.read_bytes()).hexdigest(),'bytes':p.stat().st_size}
 for role in ['mezcla','voz-sola','musica','efectos']:files[role]=f"renders/v2/{m['id']}-{role}.m4a"
 data.append({'id':m['id'],'number':i+1,'title':m['title'],'duration':m['duration_s'],'kind':'Tu voz' if i<3 else 'Voz artificial existente','files':files,'chapters':m['chapters'],'description':['Una pista · el bucle, el veredicto y la pregunta.','Una pista · cantidad, originalidad y remate.','Una pista · conversación, necesidades y escucha.','Dos músicas · del bucle a una prueba práctica.','Cuatro músicas · cliente, evidencia, criterio y acción.'][i]})
(OUT/'manifest.json').write_text(json.dumps(M,ensure_ascii=False,indent=2)+'\n')
credits=[]
records=json.loads((FW/'library/music/candidates/2026-09-30-mezclas-contexto/manifest.json').read_text())['tracks']
for r in records:credits.append(r['credit'])
cat=json.loads((FW/'library/music/catalogo-editorial.json').read_text())
credits.append(next(r['credit'] for r in cat['tracks'] if r['id']=='BGM-CAND-SB-NEON-NOMELODY')+' Cambios: extractos, filtros de música y automatización de volumen.')
(OUT/'CREDITOS.md').write_text('# Créditos y procedencia\n\n'+ '\n\n'.join(credits)+'\n\nSFX: Social Essentials Original, síntesis original del proyecto, CC0 1.0. Fuentes y hashes en manifest.json; no se reutiliza audio de los videos de referencia.\n\nMuestras privadas de evaluación. Estas pruebas no equivalen a aprobación global de canciones ni a publicación.\n')
template='''<!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Cinco pruebas de musicalización</title>
<style>*{box-sizing:border-box}body{margin:0;background:#eeeae3;color:#272b2b;font-family:system-ui,-apple-system,sans-serif}main{max-width:1080px;margin:auto;padding:48px 24px 70px}.eyebrow{font-size:12px;font-weight:700;letter-spacing:.13em;text-transform:uppercase;color:#6a756e}h1{font-size:clamp(30px,5vw,48px);letter-spacing:-.04em;margin:10px 0 16px;line-height:1.05}header p{max-width:660px;line-height:1.65;color:#59645e}.grid{display:grid;grid-template-columns:1fr 1fr;gap:20px;margin-top:32px}article{background:#fbfaf6;border:1px solid #d8ddd4;border-radius:18px;padding:24px;min-width:0}article:last-child{grid-column:1/-1}.meta{display:flex;justify-content:space-between;gap:10px;font-size:12px;color:#708178}h2{font-size:22px;margin:16px 0 8px;letter-spacing:-.02em}.desc{font-size:14px;color:#69756e;line-height:1.5;margin:0 0 24px}audio{display:block;width:100%;height:42px;margin:16px 0}.controls{display:flex;flex-wrap:wrap;gap:8px;align-items:center}.controls button{background:#234b3f;color:#fff;border:0;border-radius:9px;padding:10px 14px;font:inherit;cursor:pointer}.controls select{padding:9px;background:white;border:1px solid #cdd6cd;border-radius:9px;font:inherit;max-width:100%}.chapters{display:flex;gap:7px;flex-wrap:wrap;margin-top:18px}.chapters button{font-size:12px;border:1px solid #d7e0d5;background:transparent;color:#4e6458;padding:7px 9px;border-radius:8px;cursor:pointer}.download{font-size:12px;color:#4a6758;display:inline-block;margin-top:18px}.status{font-size:12px;color:#6c776e;min-height:16px;margin-top:12px}.error{color:#a33}details{margin-top:28px;line-height:1.6;font-size:13px;color:#627065}summary{cursor:pointer}footer{font-size:12px;color:#7b847e;margin-top:26px}a{color:#365e4c}.sr{position:absolute;width:1px;height:1px;overflow:hidden;clip-path:inset(50%)}button:focus-visible,select:focus-visible{outline:3px solid #a0c6b2;outline-offset:2px}@media(max-width:700px){main{padding:30px 16px}.grid{grid-template-columns:1fr}article{padding:20px}}
</style></head><body><main><header><div class="eyebrow">Pruebas para escuchar · 30 septiembre</div><h1>La voz guía la música.</h1><p>Cinco mensajes, cinco mezclas. Escucha la mezcla completa y compara con la voz sola en el mismo momento. Los botones de abajo te llevan a los cambios de idea.</p></header><div id="bank" class="grid"></div><details><summary>Músicas, créditos y proceso</summary><div id="credits"></div><p><a href="CREDITOS.md">Créditos completos</a> · <a href="PROCESO.md">Proceso documentado</a> · <a href="manifest.json">Archivos y medidas</a></p></details><footer>Pruebas de musicalización para tu valoración. La voz conserva su interpretación original.</footer></main>
<script>
const pieces=__DATA__;const bank=document.getElementById('bank');const audios=[];const clock=t=>Math.floor(t/60)+':'+String(Math.floor(t%60)).padStart(2,'0');
for(const p of pieces){
 const card=document.createElement('article');card.id='prueba-'+p.id;
 card.innerHTML='<div class="meta"><span>PRUEBA '+String(p.number).padStart(2,'0')+' · '+p.kind+'</span><span>'+clock(Math.round(p.duration))+'</span></div><h2>'+p.title+'</h2><p class="desc">'+p.description+'</p><div class="controls"><button class="play" aria-label="Reproducir '+p.title+'">Escuchar</button><label class="sr" for="version-'+p.id+'">Versión de '+p.title+'</label><select id="version-'+p.id+'"><option value="mezcla">Mezcla completa</option><option value="voz-sola">Voz sola</option><option value="musica">Música aplicada</option><option value="efectos">Efectos aplicados</option></select></div><audio controls preload="metadata" src="'+p.files.mezcla+'" aria-label="Audio de '+p.title+'"></audio><div class="chapters"></div><div class="status" aria-live="polite"></div><a class="download" download href="'+p.files.mezcla+'">Descargar mezcla</a>';
 bank.append(card);const a=card.querySelector('audio');audios.push(a);const btn=card.querySelector('.play');const select=card.querySelector('select');const status=card.querySelector('.status');const setStatus=s=>status.textContent=s;
 a.addEventListener('play',()=>{audios.filter(x=>x!==a).forEach(x=>x.pause());btn.textContent='Pausar';btn.setAttribute('aria-label','Pausar '+p.title)});a.addEventListener('pause',()=>{btn.textContent='Escuchar';btn.setAttribute('aria-label','Reproducir '+p.title)});a.addEventListener('error',()=>{status.classList.add('error');setStatus('No se pudo cargar el audio. Prueba el enlace de descarga.')});
 const start=()=>a.play().catch(()=>setStatus('Pulsa Escuchar para reproducir.'));btn.addEventListener('click',()=>a.paused?start():a.pause());
 select.addEventListener('change',()=>{const t=a.currentTime;const resume=!a.paused;a.pause();const loaded=()=>{a.currentTime=Math.min(t,a.duration||p.duration);if(resume)start();setStatus(select.selectedOptions[0].textContent+' · '+clock(t))};a.addEventListener('loadedmetadata',loaded,{once:true});a.src=p.files[select.value];a.load()});
 for(const [t,name] of p.chapters){const b=document.createElement('button');b.type='button';b.textContent=clock(t)+' · '+name;b.addEventListener('click',()=>{a.currentTime=t;setStatus(name+' · '+clock(t));start()});card.querySelector('.chapters').append(b)}
}
document.getElementById('credits').innerHTML=__CREDITS__;
</script></body></html>'''
ch=''.join('<p>'+html.escape(c)+'</p>' for c in credits)
(OUT/'index.html').write_text(template.replace('__DATA__',json.dumps(data,ensure_ascii=False)).replace('__CREDITS__',json.dumps(ch,ensure_ascii=False)))
print('BANK',OUT/'index.html','five mixes and controls ready')
